import React, { useState, useRef, useEffect } from "react";
import {
  LayoutGrid,
  Code2,
  Settings,
  ImagePlus,
  Copy,
  Check,
  Frame,
  RefreshCw,
  Trash2,
  Monitor,
  Tablet,
  Square,
  Smartphone,
  RectangleHorizontal,
  Grid2x2,
  AlertTriangle,
  Loader2,
  ChevronDown,
  Sparkle,
} from "lucide-react";

const NAV_ITEMS = [
  { key: "workspace", label: "Workspace", icon: Frame, disabled: false },
  { key: "views", label: "Responsive Views", icon: LayoutGrid, disabled: false },
  { key: "inspector", label: "Inspector", icon: Code2, disabled: false },
  { key: "settings", label: "Settings", icon: Settings, disabled: true },
];

function Sidebar({ active, onSelect }) {
  return (
    <aside className="w-[300px] shrink-0 border-r border-[#E5E7EB] flex flex-col pt-6 pb-4 px-3" style={{ backgroundColor: "#FAFAF9" }}>
      <div className="bg-white rounded-lg p-4 border border-[#E5E7EB] flex flex-col gap-3">
        <nav className="flex flex-col gap-3">
          {NAV_ITEMS.map(({ key, label, icon: Icon, disabled }) => {
            const isActive = active === key;
            return (
              <button
                key={key}
                type="button"
                disabled={disabled}
                onClick={() => !disabled && onSelect(key)}
                className={[
                  "group flex items-center gap-3 h-11 rounded-lg text-[16px] whitespace-nowrap transition-colors duration-150 leading-[24px]",
                  "px-4 border",
                  disabled
                    ? "text-[#B8B8B4] font-medium border-transparent cursor-not-allowed"
                    : isActive
                    ? "text-[#111827] font-semibold"
                    : "text-[#374151] font-medium border-transparent hover:bg-[#F9FAFB] hover:border-[#D1D5DB]",
                ].join(" ")}
                style={!disabled && isActive ? { backgroundColor: "#F3F4F6", borderColor: "#E5E7EB" } : undefined}
              >
                <Icon
                  size={18}
                  strokeWidth={1.75}
                  style={{ color: isActive && !disabled ? "#111827" : undefined }}
                  className={[
                    "shrink-0",
                    disabled || isActive ? "" : "text-[#6B7280] group-hover:text-[#111827]",
                  ].join(" ")}
                />
                <span>{label}</span>
                {disabled && (
                  <span className="h-5 inline-flex items-center text-[11px] uppercase tracking-[0.06em] text-[#6B7280] font-medium bg-[#F3F4F6] border border-[#E5E7EB] rounded-full px-2 shrink-0">
                    Soon
                  </span>
                )}
              </button>
            );
          })}
        </nav>
      </div>
    </aside>
  );
}

