const HOVER_HIGHLIGHT =
  "group transition-all duration-200 hover:-translate-y-0.5 hover:border-[#B0B0AC] hover:shadow-[0_1px_2px_rgba(17,17,17,0.05)]";

// --- Shared design tokens -------------------------------------------------
// Solid surfaces only — no translucency, no backdrop-filter, anywhere.
// Level 0 = border only. Level 1 = 0 4px 14px rgba(17,17,17,0.06).
const GLASS_TRANSITION = "transition-all duration-[180ms] ease-out";
const GLASS_FOCUS_RING =
  "focus:outline-none focus-visible:ring-2 focus-visible:ring-black/10";
const GLASS_PRESS = "active:scale-[0.98]";
// Selected state mirrors the sidebar's "Workspace" reference style exactly:
// white surface, strong black border, black text — never a filled background.
const GLASS_CHIP_ACTIVE =
  "bg-white text-[#111111] border-2 border-[#111111] font-semibold shadow-[0_1px_2px_rgba(17,17,17,0.05)]";
const GLASS_CHIP_INACTIVE =
  "bg-white text-[#6B7280] border border-[#D1D5DB] font-medium hover:bg-[#F9FAFB] hover:border-[#9CA3AF]";

// Button primitives — every button in the product uses exactly one of
// these three variants. Primary is solid black; Secondary/Ghost is a true
// outline (white fill, visible border); Destructive is the danger
// outline reserved for irreversible actions.
const GLASS_BUTTON_GHOST =
  "bg-white border border-[#E5E7EB] text-[#111827] hover:bg-[#F3F4F6]";
const GLASS_BUTTON_DESTRUCTIVE =
  "bg-white border border-[#FECACA] text-[#B91C1C] hover:bg-[#FEF2F2]";
const GLASS_BUTTON_DISABLED = "text-[#9CA3AF] border border-[#E5E7EB] cursor-not-allowed";

function GlassButton({ variant = "ghost", disabled, className = "", style, children, ...props }) {
  const variantClass = disabled
    ? GLASS_BUTTON_DISABLED
    : variant === "primary"
    ? "text-white border border-transparent"
    : variant === "destructive"
    ? GLASS_BUTTON_DESTRUCTIVE
    : GLASS_BUTTON_GHOST;
  const primaryStyle =
    disabled
      ? { backgroundColor: "#F3F4F6" }
      : variant === "primary"
      ? { backgroundColor: "#111111" }
      : undefined;

  return (
    <button
      type="button"
      disabled={disabled}
      className={[
        "flex items-center justify-center gap-2 py-3 px-4 rounded-lg text-[14px] font-medium border",
        "transition-colors duration-150 active:scale-[0.98]",
        disabled ? "opacity-60" : "",
        !disabled && variant === "primary" ? "hover:bg-[#262626]" : "",
        GLASS_FOCUS_RING,
        variantClass,
        className,
      ].filter(Boolean).join(" ")}
      style={{ ...primaryStyle, ...style }}
      {...props}
    >
      {children}
    </button>
  );
}

function ratioSlug(ratioLabel) {
  return ratioLabel.replace(":", "x");
}

const FORMAT_MIME = { png: "image/png", jpg: "image/jpeg", webp: "image/webp" };
const FORMAT_EXT = { png: "png", jpg: "jpg", webp: "webp" };
const QUALITY_SCALE = { 1: 1, 2: 2, 3: 3 };

function loadImageEl(src) {
  return new Promise((resolve, reject) => {
    const img = new window.Image();
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

// --- Crop Intelligence engine -------------------------------------------
// Reusable smart-crop calculator. Given source image dimensions, a target
// aspect ratio, a focal point (0-100%), and an aspect-ratio-specific bias,
// returns the crop rectangle { x, y, width, height } in source-pixel space.
// This is the single source of truth used by BOTH the live preview render
// and the canvas export, so preview and export always match exactly.

const DEFAULT_CROP_BIAS = { xBlend: 1, yBlend: 1, xShift: 0, yShift: 0 };

// Per-frame bias tunes how strongly the crop follows the raw focal point
// vs. pulling toward center, plus a directional nudge (rule-of-thirds-style)
// on the axis most likely to be cropped for that aspect ratio. There is one
// bias table per Crop Priority mode, selectable live from the Crop
// Intelligence panel.
const CROP_PRIORITY_BIAS = {
  balanced: {
    desktop: { xBlend: 1, yBlend: 0.85, xShift: 0, yShift: -0.06 },
    tablet: { xBlend: 1, yBlend: 0.9, xShift: 0, yShift: -0.1 },
    mobile: { xBlend: 1, yBlend: 1, xShift: 0, yShift: 0 },
    square: { xBlend: 0.6, yBlend: 0.6, xShift: 0, yShift: 0 },
    banner: { xBlend: 1, yBlend: 1, xShift: 0, yShift: -0.05 },
  },
  // Subject First — Mobile/Tablet preserve the subject aggressively: full
  // fidelity to the raw focal point, no centering pull.
  subject: {
    desktop: { xBlend: 1, yBlend: 0.85, xShift: 0, yShift: -0.06 },
    tablet: { xBlend: 1, yBlend: 1, xShift: 0, yShift: 0 },
    mobile: { xBlend: 1, yBlend: 1, xShift: 0, yShift: 0 },
    square: { xBlend: 0.85, yBlend: 0.85, xShift: 0, yShift: 0 },
    banner: { xBlend: 1, yBlend: 1, xShift: 0, yShift: -0.05 },
  },
  // Landscape Priority — Desktop/Banner preserve scenery: blend toward
  // center so more of the wider composition survives the crop.
  landscape: {
    desktop: { xBlend: 0.55, yBlend: 0.5, xShift: 0, yShift: -0.03 },
    tablet: { xBlend: 1, yBlend: 0.9, xShift: 0, yShift: -0.1 },
    mobile: { xBlend: 1, yBlend: 1, xShift: 0, yShift: 0 },
    square: { xBlend: 0.6, yBlend: 0.6, xShift: 0, yShift: 0 },
    banner: { xBlend: 0.55, yBlend: 0.5, xShift: 0, yShift: -0.03 },
  },
};

// Resolves the bias to use for a given frame. When Smart Crop is OFF, every
// frame falls back to DEFAULT_CROP_BIAS, which reduces computeSmartCrop to
// plain focal-point-driven cropping — i.e. the legacy object-position
// behavior — so flipping the switch is a true apples-to-apples comparison.
function getActiveCropBias(frameKey, smartCropEnabled, cropPriority) {
  if (!smartCropEnabled) return DEFAULT_CROP_BIAS;
  const table = CROP_PRIORITY_BIAS[cropPriority] || CROP_PRIORITY_BIAS.balanced;
  return table[frameKey] || DEFAULT_CROP_BIAS;
}

function computeSmartCrop({ naturalWidth, naturalHeight, targetRatio, focalPoint, bias }) {
  const b = bias || DEFAULT_CROP_BIAS;
  const naturalRatio = naturalWidth / naturalHeight;

  // Largest crop window matching targetRatio that fits inside the source.
  let cropW, cropH;
  if (naturalRatio > targetRatio) {
    cropH = naturalHeight;
    cropW = cropH * targetRatio;
  } else {
    cropW = naturalWidth;
    cropH = cropW / targetRatio;
  }

  const fx = focalPoint.x / 100;
  const fy = focalPoint.y / 100;

  const clamp01 = (v) => Math.min(1, Math.max(0, v));

  // Blend the raw focal fraction toward center per-axis, then apply the
  // directional shift. Clamping to [0,1] here is what keeps the focal
  // point visible near edges: the crop window slides inward instead of
  // overflowing the image bounds ("edge intelligence").
  const anchorX = clamp01(0.5 + (fx - 0.5) * b.xBlend + (b.xShift || 0));
  const anchorY = clamp01(0.5 + (fy - 0.5) * b.yBlend + (b.yShift || 0));

  const x = anchorX * (naturalWidth - cropW);
  const y = anchorY * (naturalHeight - cropH);

  return { x, y, width: cropW, height: cropH };
}

function getCroppedCanvas({ img, frame, focalPoint, scale, smartCropEnabled, cropPriority }) {
  const targetRatio = frame.width / frame.height;
  const bias = getActiveCropBias(frame.key, smartCropEnabled, cropPriority);
  const { x, y, width, height } = computeSmartCrop({
    naturalWidth: img.naturalWidth,
    naturalHeight: img.naturalHeight,
    targetRatio,
    focalPoint,
    bias,
  });

  const canvas = document.createElement("canvas");
  canvas.width = Math.round(frame.width * scale);
  canvas.height = Math.round(frame.height * scale);
  const ctx = canvas.getContext("2d");
  ctx.drawImage(img, x, y, width, height, 0, 0, canvas.width, canvas.height);
  return canvas;
}

function canvasToBlob(canvas, mime) {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error("Export failed"))),
      mime,
      mime === "image/png" ? undefined : 0.92
    );
  });
}

async function exportFrameBlob({ image, frame, focalPoint, format, quality, smartCropEnabled, cropPriority }) {
  const img = await loadImageEl(image.src);
  const canvas = getCroppedCanvas({
    img,
    frame,
    focalPoint,
    scale: QUALITY_SCALE[quality],
    smartCropEnabled,
    cropPriority,
  });
  return canvasToBlob(canvas, FORMAT_MIME[format]);
}

function triggerDownload(blob, filename) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}

function assetFilename(frame, format) {
  return `framepoint-${frame.key}-${ratioSlug(frame.ratioLabel)}.${FORMAT_EXT[format]}`;
}

const SAFE_ZONES = {
  desktop: { top: 5, right: 5, bottom: 5, left: 5, kind: "rect" },
  tablet: { top: 6, right: 5, bottom: 6, left: 5, kind: "rect" },
  mobile: { top: 7, right: 4, bottom: 12, left: 4, kind: "device" },
  square: { top: 8, right: 8, bottom: 8, left: 8, kind: "rect" },
  banner: { top: 10, right: 6, bottom: 10, left: 6, kind: "rect" },
};

function getSafeAreaStatus(frameKey, focalPoint) {
  const zone = SAFE_ZONES[frameKey];
  if (!zone || !focalPoint) return true;
  const insideX = focalPoint.x >= zone.left && focalPoint.x <= 100 - zone.right;
  const insideY = focalPoint.y >= zone.top && focalPoint.y <= 100 - zone.bottom;
  return insideX && insideY;
}

const SAFE_GUIDE_BOX_STYLE = {
  borderWidth: 2,
  borderStyle: "dashed",
  borderColor: "rgba(255,255,255,0.8)",
  boxShadow: "0 0 0 1px rgba(0,0,0,0.6)",
};

function SafeAreaGuide({ frameKey }) {
  const zone = SAFE_ZONES[frameKey];
  if (!zone) return null;

  const guideBox = (
    <div
      className="absolute rounded-md pointer-events-none"
      style={{
        top: `${zone.top}%`,
        right: `${zone.right}%`,
        bottom: `${zone.bottom}%`,
        left: `${zone.left}%`,
        ...SAFE_GUIDE_BOX_STYLE,
      }}
    />
  );

  if (zone.kind !== "device") {
    return guideBox;
  }

  return (
    <>
      <div
        className="absolute inset-x-0 top-0 bg-black/[0.22] pointer-events-none"
        style={{ height: `${zone.top}%` }}
      />
      <div
        className="absolute inset-x-0 bottom-0 bg-black/[0.22] pointer-events-none"
        style={{ height: `${zone.bottom}%` }}
      />
      {guideBox}
    </>
  );
}

const CROP_PRIORITY_LABELS = {
  balanced: "Balanced",
  subject: "Subject First",
  landscape: "Landscape",
};

function CropCorners() {
  const base =
    "absolute w-5 h-5 border-white/80 opacity-80 transition-opacity duration-200 group-hover:opacity-100 pointer-events-none";
  return (
    <>
      <span className={`${base} top-1.5 left-1.5 border-t-2 border-l-2 rounded-tl-[4px]`} />
      <span className={`${base} top-1.5 right-1.5 border-t-2 border-r-2 rounded-tr-[4px]`} />
      <span className={`${base} bottom-1.5 left-1.5 border-b-2 border-l-2 rounded-bl-[4px]`} />
      <span className={`${base} bottom-1.5 right-1.5 border-b-2 border-r-2 rounded-br-[4px]`} />
    </>
  );
}

function PreviewContent({ image, frame, focalPoint, ratio, roundedClass, safeArea, safeAreaOpacity = 1, smartCropEnabled, cropPriority }) {
  const targetRatio = frame.width / frame.height;
  const bias = getActiveCropBias(frame.key, smartCropEnabled, cropPriority);
  const crop = computeSmartCrop({
    naturalWidth: image.width,
    naturalHeight: image.height,
    targetRatio,
    focalPoint,
    bias,
  });

  const widthPct = (image.width / crop.width) * 100;
  const heightPct = (image.height / crop.height) * 100;
  const leftPct = -(crop.x / crop.width) * 100;
  const topPct = -(crop.y / crop.height) * 100;

  return (
    <div
      className={`relative w-full overflow-hidden bg-[#F1F1EE] ${roundedClass}`}
      style={{ aspectRatio: ratio }}
    >
      <img
        src={image.src}
        alt="preview"
        className="absolute max-w-none select-none transition-all duration-[250ms] ease-out"
        style={{
          width: `${widthPct}%`,
          height: `${heightPct}%`,
          left: `${leftPct}%`,
          top: `${topPct}%`,
        }}
      />
      {safeArea && (
        <div
          className="absolute inset-0 transition-opacity duration-300 ease-out [animation:fp-fade-in_180ms_ease-out]"
          style={{ opacity: safeAreaOpacity }}
        >
          <SafeAreaGuide frameKey={frame.key} />
        </div>
      )}
      <CropCorners />
    </div>
  );
}

