function SelectedIndicator({ checked }) {
  if (!checked) return null;
  return <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: "#111111" }} />;
}

function PreviewCheckbox({ checked, onToggle }) {
  return (
    <label
      onClick={(e) => e.stopPropagation()}
      className="absolute -top-3 -left-3 z-10 cursor-pointer group"
    >
      <input
        type="checkbox"
        checked={checked}
        onChange={onToggle}
        className="sr-only peer"
      />
      <div
        className="w-5 h-5 rounded-md flex items-center justify-center transition-colors duration-150 peer-focus-visible:ring-2 peer-focus-visible:ring-[#D1FAE5] peer-focus-visible:ring-offset-1"
        style={{
          backgroundColor: checked ? "#111827" : "#FFFFFF",
          border: checked ? "1.5px solid #111827" : "1.5px solid #4B5563",
        }}
        onMouseEnter={(e) => {
          if (!checked) {
            e.currentTarget.style.backgroundColor = "#F9FAFB";
            e.currentTarget.style.border = "1.5px solid #374151";
          }
        }}
        onMouseLeave={(e) => {
          if (!checked) {
            e.currentTarget.style.backgroundColor = "#FFFFFF";
            e.currentTarget.style.border = "1.5px solid #4B5563";
          }
        }}
      >
        {checked && <Check size={12} strokeWidth={3} style={{ color: "#FFFFFF" }} />}
      </div>
    </label>
  );
}

