function ResponsiveViews({ image, focalPoint, smartCropEnabled, cropPriority, safeArea, setSafeArea, safeAreaOpacity, scrollRootRef, bumpSafeAreaActivity, selected, setSelected, format, setFormat, quality, setQuality }) {
  const [selectedViewport, setSelectedViewport] = useState("all");

  const cardRefs = useRef({});
  const suppressObserverRef = useRef(false);
  const suppressTimeoutRef = useRef(null);

  const allSelected = PREVIEW_FRAMES.every((f) => selected[f.key]);
  const selectedFrames = PREVIEW_FRAMES.filter((f) => selected[f.key]);

  const handleToggleOne = (key) => {
    setSelected((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const handleToggleAll = () => {
    const next = !allSelected;
    setSelected(Object.fromEntries(PREVIEW_FRAMES.map((f) => [f.key, next])));
    // "Clear All" restores Safe Area to its default (fully visible) state.
    if (!next) bumpSafeAreaActivity?.();
  };

  // Auto-detect which preview card is in view as the user scrolls, and
  // keep the matching toolbar chip active (Feature 1: chip is the source
  // of truth, driven either by click or by scroll position).
  useEffect(() => {
    const root = scrollRootRef?.current;
    if (!root) return;
    const observer = new IntersectionObserver(
      (entries) => {
        if (suppressObserverRef.current) return;
        let best = null;
        for (const entry of entries) {
          if (entry.isIntersecting && (!best || entry.intersectionRatio > best.intersectionRatio)) {
            best = entry;
          }
        }
        const key = best?.target?.dataset?.frameKey;
        if (key) setSelectedViewport(key);
      },
      { root, threshold: [0.4, 0.6, 0.8] }
    );
    Object.values(cardRefs.current).forEach((el) => el && observer.observe(el));
    return () => observer.disconnect();
  }, [scrollRootRef]);

  // Clicking a chip smoothly scrolls to that card and suppresses the
  // observer briefly so the programmatic scroll doesn't fight the click.
  const handleViewportSelect = (key) => {
    setSelectedViewport(key);
    bumpSafeAreaActivity?.();
    suppressObserverRef.current = true;
    if (suppressTimeoutRef.current) clearTimeout(suppressTimeoutRef.current);

    const target = key === "all" ? cardRefs.current[PREVIEW_FRAMES[0].key] : cardRefs.current[key];
    target?.scrollIntoView({ behavior: "smooth", block: "start" });

    suppressTimeoutRef.current = setTimeout(() => {
      suppressObserverRef.current = false;
    }, 600);
  };

  const safeCount = PREVIEW_FRAMES.filter((f) => getSafeAreaStatus(f.key, focalPoint)).length;
  const activeOption =
    VIEWPORT_TOOLBAR_OPTIONS.find((o) => o.key === selectedViewport) || VIEWPORT_TOOLBAR_OPTIONS[0];

  return (
    <div className="col-span-12">
      <ExportPanel
        activeLabel={activeOption.label}
        safeCount={safeCount}
        totalCount={PREVIEW_FRAMES.length}
        cropPriorityLabel={smartCropEnabled ? CROP_PRIORITY_LABELS[cropPriority] || "Balanced" : "Legacy"}
        allSelected={allSelected}
        onToggleAll={handleToggleAll}
      />

      {/* Sticky within the workspace's own scroll container (Feature 8). */}
      <div className="sticky top-0 z-20 py-3 mb-4 flex justify-center">
        <div className="inline-flex items-center h-14 bg-white/90 backdrop-blur-[12px] border border-[#E5E7EB] rounded-full shadow-[0_4px_16px_rgba(17,17,17,0.08)] px-4">
          <ViewportToolbar value={selectedViewport} onChange={handleViewportSelect} />
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 items-start">
        {PREVIEW_FRAMES.map((frame) => {
          const emphasis =
            selectedViewport === "all"
              ? "neutral"
              : selectedViewport === frame.key
              ? "active"
              : "dim";
          return (
            <div
              key={frame.key}
              ref={(el) => {
                cardRefs.current[frame.key] = el;
              }}
              data-frame-key={frame.key}
              className={[
                "scroll-mt-20 bg-white rounded-lg p-6 border-2 transition-colors duration-[250ms] ease-out",
                "shadow-[0_1px_2px_rgba(17,17,17,0.05)]",
                emphasis === "active" ? "border-[#111111]" : "border-[#EDEFF2]",
              ].join(" ")}
            >
              <PreviewCard
                frame={frame}
                image={image}
                safeArea={safeArea}
                safeAreaOpacity={safeAreaOpacity}
                checked={!!selected[frame.key]}
                onToggle={() => handleToggleOne(frame.key)}
                focalPoint={focalPoint}
                smartCropEnabled={smartCropEnabled}
                cropPriority={cropPriority}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

function FocalMarker({ x, y, isDragging, onPointerDown }) {
  return (
    <div
      onPointerDown={onPointerDown}
      onClick={(e) => e.stopPropagation()}
      className="absolute z-10 -translate-x-1/2 -translate-y-1/2 cursor-grab active:cursor-grabbing touch-none"
      style={{
        left: `${x}%`,
        top: `${y}%`,
        transition: isDragging
          ? "transform 180ms ease-out"
          : "left 250ms ease-out, top 250ms ease-out, transform 180ms ease-out",
      }}
    >
      {/* Frosted glass ring: no solid fill — backdrop-blur-lg lets the
          image color show through. Sizes: idle 28px, hover 34px,
          dragging 38px. A subtle white glow appears only while dragging. */}
      <div
        className={[
          "relative rounded-full bg-transparent backdrop-blur-lg border border-white",
          "transition-all duration-[180ms] ease-out",
          isDragging ? "" : "w-7 h-7 hover:w-[34px] hover:h-[34px]",
        ].join(" ")}
        style={
          isDragging
            ? {
                width: 38,
                height: 38,
                boxShadow:
                  "0 0 0 1px rgba(255,255,255,0.4), 0 0 18px 2px rgba(255,255,255,0.35), 0 6px 16px rgba(0,0,0,0.22)",
              }
            : { boxShadow: "0 1px 6px rgba(0,0,0,0.18)" }
        }
      >
        {/* Adaptive-contrast center dot: 4px white fill + 1px dark hairline
            outline keeps it visible on both light and dark image regions
            without relying on blend-mode support. */}
        <span
          className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-1 h-1 rounded-full bg-white"
          style={{ boxShadow: "0 0 0 1px rgba(0,0,0,0.55)" }}
        />
      </div>
    </div>
  );
}

function Workspace({ image, setImage, focalPoint, setFocalPoint, smartCropEnabled, setSmartCropEnabled, cropPriority, setCropPriority, safeArea, setSafeArea, userDisabledSafeAreaRef, safeAreaOpacity, bumpSafeAreaActivity, selected, setSelected, exportFormat, setExportFormat, quality, setQuality }) {
  const [isDragging, setIsDragging] = useState(false);
  const [uploadError, setUploadError] = useState(false);
  const [isPositioning, setIsPositioning] = useState(false);
  const inputRef = useRef(null);
  const imageWrapRef = useRef(null);
  const scrollRootRef = useRef(null);

  const loadFile = (file) => {
    if (!file || !ACCEPTED_TYPES.includes(file.type)) {
      setUploadError(true);
      return;
    }
    setUploadError(false);

    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target.result;
      const img = new window.Image();
      img.onload = () => {
        setImage({
          src: dataUrl,
          name: file.name,
          size: file.size,
          width: img.naturalWidth,
          height: img.naturalHeight,
        });
        setFocalPoint({ x: 50, y: 50 });
        // Auto-detect the export format from the uploaded file's type, so
        // the correct PNG/JPG/WebP chip is pre-selected in the Inspector.
        if (file.type === "image/png") setExportFormat?.("png");
        else if (file.type === "image/jpeg") setExportFormat?.("jpg");
        else if (file.type === "image/webp") setExportFormat?.("webp");
        // New image: Safe Area starts hidden again and the "user disabled
        // it" preference is cleared, so auto-show can trigger fresh.
        setSafeArea(false);
        userDisabledSafeAreaRef.current = false;
      };
      img.src = dataUrl;
    };
    reader.readAsDataURL(file);
  };

  const handleInputChange = (e) => {
    loadFile(e.target.files?.[0]);
    e.target.value = "";
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);
    loadFile(e.dataTransfer.files?.[0]);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = () => setIsDragging(false);

  const handleRemove = () => {
    setImage(null);
    setUploadError(false);
    setFocalPoint({ x: 50, y: 50 });
    setSafeArea(false);
    userDisabledSafeAreaRef.current = false;
    setExportFormat?.(null);
  };

  // Manual toggle from the Safe Area switch. Turning it OFF is remembered
  // for the rest of this image's session (auto-show won't override it)
  // until a new image is uploaded or the current one is removed.
  const handleSafeAreaChange = (next) => {
    setSafeArea(next);
    if (!next) userDisabledSafeAreaRef.current = true;
  };

  // Safe Area automatically becomes visible on the user's first focal-point
  // interaction (click, tap, or drag), unless they've manually dismissed it,
  // and every interaction resets the 2s idle-dim timer so it stays fully
  // visible while actively dragging.
  const handleFocalActivity = () => {
    if (!userDisabledSafeAreaRef.current) setSafeArea(true);
    bumpSafeAreaActivity();
  };

  const updateFocalFromClientPos = (clientX, clientY) => {
    const rect = imageWrapRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = Math.min(100, Math.max(0, ((clientX - rect.left) / rect.width) * 100));
    const y = Math.min(100, Math.max(0, ((clientY - rect.top) / rect.height) * 100));
    setFocalPoint({ x, y });
  };

  const dragMovedRef = useRef(false);

  const handleMarkerPointerDown = (e) => {
    e.preventDefault();
    e.stopPropagation();
    dragMovedRef.current = false;
    setIsPositioning(true);
    handleFocalActivity();
    updateFocalFromClientPos(e.clientX, e.clientY);
  };

  useEffect(() => {
    if (!isPositioning) return;
    const onMove = (e) => {
      dragMovedRef.current = true;
      bumpSafeAreaActivity();
      updateFocalFromClientPos(e.clientX, e.clientY);
    };
    const onUp = () => setIsPositioning(false);
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
    };
  }, [isPositioning]);

  // Click/tap anywhere on the image sets the focus target immediately.
  // Ignored when it's the tail end of a drag that started on the marker
  // (dragMovedRef guards against the marker's own click bubbling here).
  const handleImageClick = (e) => {
    if (dragMovedRef.current) {
      dragMovedRef.current = false;
      return;
    }
    handleFocalActivity();
    updateFocalFromClientPos(e.clientX, e.clientY);
  };

  return (
    <main
      ref={scrollRootRef}
      className="flex-1 min-w-0 grid grid-cols-12 gap-0 pt-6 pr-6 pb-6 pl-6 auto-rows-min overflow-y-auto"
    >
      <div className="col-span-12 lg:col-span-8 mb-4">
        <h1 className="text-[18px] font-semibold text-[#1F2937] tracking-tight leading-[1.4]">
          Responsive Art Direction
        </h1>
        <p className="text-[13px] font-normal text-[#4B5563] mt-3 leading-[1.5]">
          Preserve focal points across every screen size.
        </p>
      </div>

      <input
        ref={inputRef}
        type="file"
        accept="image/jpeg,image/png,image/webp"
        className="hidden"
        onChange={handleInputChange}
      />

      {!image ? (
        <div
          onClick={() => inputRef.current?.click()}
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          className={[
            "col-span-12 min-h-[560px] w-full rounded-2xl border border-dashed p-12 flex flex-col items-center justify-center text-center cursor-pointer transition-colors duration-[150ms] ease-out relative overflow-hidden",
            isDragging ? "border-[#9CA3AF]" : "border-[#D1D5DB]",
          ].join(" ")}
          style={{
            backgroundColor: isDragging ? "#EFF1F4" : "#F3F4F6",
            animation: isDragging ? "fp-border-pulse 1s ease-in-out infinite" : undefined,
          }}
          onMouseEnter={(e) => {
            if (!isDragging) {
              e.currentTarget.style.backgroundColor = "#EFF1F4";
              e.currentTarget.style.borderColor = "#9CA3AF";
            }
          }}
          onMouseLeave={(e) => {
            if (!isDragging) {
              e.currentTarget.style.backgroundColor = "#F3F4F6";
              e.currentTarget.style.borderColor = "#D1D5DB";
            }
          }}
        >
          <div
            className="flex flex-col items-center text-center max-w-[420px]"
            style={{ filter: uploadError ? "blur(3px)" : "none", transition: "filter 200ms ease-out" }}
          >
            <div
              className="relative w-14 h-14 flex items-center justify-center"
              style={{ transform: isDragging ? "translateY(-6px)" : undefined }}
            >
              <ImagePlus size={28} strokeWidth={1.75} className="text-[#9CA3AF]" />
              <Sparkle
                size={14}
                className="absolute"
                style={{ left: "45px", top: "10px", fill: "#9CA3AF", color: "#9CA3AF", animation: "fp-twinkle 2.4s ease-in-out infinite", animationDelay: "0s" }}
              />
              <Sparkle
                size={9}
                className="absolute"
                style={{ left: "54px", top: "-1px", fill: "#6B7280", color: "#6B7280", animation: "fp-twinkle 2.8s ease-in-out infinite", animationDelay: "0.7s" }}
              />
              <Sparkle
                size={6}
                className="absolute"
                style={{ left: "65px", top: "14px", fill: "#111111", color: "#111111", animation: "fp-twinkle 2.2s ease-in-out infinite", animationDelay: "1.3s" }}
              />
            </div>
            <div className="mt-4">
              <p className="text-[24px] font-semibold text-[#111827]">
                {isDragging ? "Drop it here" : "Drag and drop an image"}
              </p>
              <p className="text-[14px] font-normal text-[#4B5563] mt-2 leading-[22px]">
                Your focus point follows automatically — every size, every time.
              </p>
            </div>
            <GlassButton
              variant="primary"
              onClick={(e) => {
                e.stopPropagation();
                inputRef.current?.click();
              }}
              className="mt-6 h-11 rounded-lg px-5"
            >
              Choose Image
            </GlassButton>
          </div>

          {uploadError && (
            <div
              className="absolute inset-0 flex items-center justify-center"
              style={{ backgroundColor: "rgba(17,24,39,0.55)", backdropFilter: "blur(2px)" }}
            >
              <div className="flex flex-col items-center gap-2 px-6">
                <AlertTriangle size={22} strokeWidth={1.75} className="text-[#FCA5A5]" />
                <p className="text-[14px] font-semibold text-white">That file type isn't supported</p>
                <p className="text-[13px] font-normal text-[#E5E7EB]">Try JPG, PNG, or WebP instead.</p>
              </div>
            </div>
          )}
        </div>
      ) : (
        <>
          <div className="col-span-12 min-h-[440px] rounded-2xl border border-[#E5E7EB] bg-[#FAFAF9] shadow-[0_1px_2px_rgba(17,17,17,0.05)] flex items-center justify-center overflow-hidden p-4">
            <div
              key={image.src}
              ref={imageWrapRef}
              onClick={handleImageClick}
              className="relative inline-block leading-none cursor-crosshair [animation:fp-fade-in_320ms_ease-out]"
            >
              <img
                src={image.src}
                alt={image.name}
                draggable={false}
                className="max-w-full max-h-[360px] rounded-lg object-contain block select-none"
              />
              <FocalMarker
                x={focalPoint.x}
                y={focalPoint.y}
                isDragging={isPositioning}
                onPointerDown={handleMarkerPointerDown}
              />
            </div>
          </div>

          <div className="col-span-12 flex items-center justify-between flex-wrap gap-4 mt-4 mb-4">
            <div className="inline-flex items-center gap-2 text-[12px] font-normal text-[#6B7280]">
              <span>{image.name.split(".").pop().toUpperCase()}</span>
              <span className="text-[#C6C6C2]">•</span>
              <span>
                {image.width}×{image.height}
              </span>
              <span className="text-[#C6C6C2]">•</span>
              <span>{formatFileSize(image.size)}</span>
            </div>

            <div className="flex items-center gap-3">
              <GlassButton variant="ghost" onClick={() => inputRef.current?.click()} className="h-10 rounded-lg">
                <RefreshCw size={14} strokeWidth={1.75} />
                Replace Image
              </GlassButton>
              <GlassButton variant="destructive" onClick={handleRemove} className="h-10 rounded-lg">
                <Trash2 size={14} strokeWidth={1.75} />
                Remove Image
              </GlassButton>
            </div>
          </div>

          <CropIntelligencePanel />

          <ResponsiveViews
            image={image}
            focalPoint={focalPoint}
            smartCropEnabled={smartCropEnabled}
            cropPriority={cropPriority}
            safeArea={safeArea}
            setSafeArea={handleSafeAreaChange}
            safeAreaOpacity={safeAreaOpacity}
            scrollRootRef={scrollRootRef}
            bumpSafeAreaActivity={bumpSafeAreaActivity}
            selected={selected}
            setSelected={setSelected}
            format={exportFormat}
            setFormat={setExportFormat}
            quality={quality}
            setQuality={setQuality}
          />
        </>
      )}
    </main>
  );
}

function InspectorField({ label, value, pulse, editable, onChange, disabled }) {
  const isEmpty = value === "—";
  const boxClass = [
    "mt-1.5 h-11 rounded-lg flex items-center px-3 text-[14px] leading-5 border transition-colors duration-200",
    pulse ? "bg-[#F3F4F6] border-[#111111]" : "bg-white border-[#D1D5DB]",
    isEmpty ? "font-normal text-[#9CA3AF]" : "font-medium text-[#111827]",
  ].join(" ");

  return (
    <div>
      <label className="text-[12px] font-medium text-[#6B7280]">{label}</label>
      {editable ? (
        <div className="relative">
          <input
            type="number"
            min={0}
            max={100}
            value={value}
            onChange={onChange}
            disabled={disabled}
            className={`${boxClass} w-full pr-6 text-center outline-none focus:border-[#111111] disabled:cursor-not-allowed`}
          />
          <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[12px] text-[#9CA3AF]">
            %
          </span>
        </div>
      ) : (
        <div className={boxClass}>{value}</div>
      )}
    </div>
  );
}

function InspectorCard({ title, children }) {
  return (
    <div className="bg-white rounded-lg p-4 border border-[#E5E7EB] flex flex-col gap-3">
      <p className="text-[16px] font-semibold text-[#1F2937]">{title}</p>
      {children}
    </div>
  );
}

const EXPORT_ASSET_FORMAT_OPTIONS = FORMAT_OPTIONS;

function ExportFormatPill({ value, onChange }) {
  return (
    <div className="flex items-center gap-2 flex-wrap">
      {EXPORT_ASSET_FORMAT_OPTIONS.map((opt) => {
        const active = value === opt.value;
        return (
          <button
            key={opt.value}
            type="button"
            onClick={() => onChange(opt.value)}
            className={[
              "px-4 py-3 rounded-lg text-[14px] flex items-center justify-center border font-medium",
              "transition-all duration-[180ms] ease-out active:scale-[0.98]",
              "focus:outline-none focus-visible:ring-2 focus-visible:ring-black/10",
              active
                ? "text-[#111111]"
                : "bg-white text-[#374151] border-transparent hover:bg-[#F9FAFB]",
            ].join(" ")}
            style={active ? { backgroundColor: "#F3F4F6", borderColor: "#E5E7EB" } : undefined}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

function ExportQueueRow({ label, status }) {
  return (
    <div className="flex items-center justify-between text-[12.5px] text-[#111111] py-1">
      <span>{label}</span>
      {status === "exporting" && <Loader2 size={14} strokeWidth={2} className="animate-spin text-[#6B7280]" />}
      {status === "done" && <Check size={14} strokeWidth={2.25} className="text-[#16A34A]" />}
    </div>
  );
}

function ExportAssetsCard({ image, focalPoint, smartCropEnabled, cropPriority, selected, hasImage, format, setFormat, quality, setQuality }) {
  // idle | exporting | success
  const [status, setStatus] = useState("idle");
  const [activeAction, setActiveAction] = useState(null); // "all" | "selected"
  const [currentLabel, setCurrentLabel] = useState("");
  const [currentIndex, setCurrentIndex] = useState(0);
  const [queue, setQueue] = useState([]); // [{ key, label, status }]

  const selectedFrames = PREVIEW_FRAMES.filter((f) => selected?.[f.key]);
  const selectedCount = selectedFrames.length;

  const runExport = async (frames, action) => {
    if (!hasImage || status === "exporting" || frames.length === 0) return;

    setStatus("exporting");
    setActiveAction(action);
    setQueue(frames.map((f) => ({ key: f.key, label: f.label, status: "pending" })));

    for (let i = 0; i < frames.length; i++) {
      const frame = frames[i];
      setCurrentIndex(i + 1);
      setCurrentLabel(frame.label);
      setQueue((prev) =>
        prev.map((row) => (row.key === frame.key ? { ...row, status: "exporting" } : row))
      );

      try {
        const blob = await exportFrameBlob({
          image,
          frame,
          focalPoint,
          format,
          quality,
          smartCropEnabled,
          cropPriority,
        });
        triggerDownload(blob, assetFilename(frame, format));
      } catch {
        // Skip this asset on failure and continue with the rest of the queue.
      }

      setQueue((prev) =>
        prev.map((row) => (row.key === frame.key ? { ...row, status: "done" } : row))
      );
    }

    setStatus("success");
    setTimeout(() => {
      setStatus("idle");
      setActiveAction(null);
      setQueue([]);
      setCurrentLabel("");
      setCurrentIndex(0);
    }, 3000);
  };

  const handleExportSelected = () => runExport(selectedFrames, "selected");

  const qualityLabel = QUALITY_OPTIONS.find((o) => o.value === quality)?.label || "High (2×)";
  const formatLabel = FORMAT_OPTIONS.find((o) => o.value === format)?.label || "PNG";

  return (
    <InspectorCard title="Export Assets">
      <p className="text-[12px] font-normal text-[#4B5563] -mt-1">
        Selected responsive previews.
      </p>

      <div>
        <label className="text-[12px] font-medium text-[#6B7280]">Export Format</label>
        <select
          value={format || FORMAT_OPTIONS[0].value}
          onChange={(e) => setFormat(e.target.value)}
          disabled={!hasImage}
          className="mt-1.5 w-full h-11 px-4 rounded-lg text-[14px] font-medium leading-5 text-[#111827] bg-white border border-[#D1D5DB] cursor-pointer transition-colors duration-200 focus:border-[#111111] focus:outline-none disabled:cursor-not-allowed disabled:font-normal disabled:text-[#94A3B8]"
        >
          {FORMAT_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <div>
        <label className="text-[12px] font-medium text-[#6B7280]">Export Quality</label>
        <select
          value={quality}
          onChange={(e) => setQuality(Number(e.target.value))}
          disabled={!hasImage || status === "exporting"}
          className="mt-1.5 w-full h-11 px-4 rounded-lg text-[14px] font-medium leading-5 text-[#111827] bg-white border border-[#D1D5DB] cursor-pointer transition-colors duration-200 focus:border-[#111111] focus:outline-none disabled:cursor-not-allowed disabled:font-normal disabled:text-[#94A3B8]"
        >
          {QUALITY_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
      </div>

      <div className="flex flex-col gap-2">
        {/* Export Selected — the only CTA in the Inspector panel */}
        <button
          type="button"
          onClick={handleExportSelected}
          disabled={!hasImage || status === "exporting" || selectedCount === 0}
          className={[
            "w-full flex items-center justify-center gap-2 h-11 rounded-lg text-[14px] font-medium border",
            "transition-colors duration-150",
            !hasImage || status === "exporting" || selectedCount === 0
              ? "border-transparent cursor-not-allowed"
              : "border-transparent hover:opacity-90",
          ].join(" ")}
          style={
            !hasImage || status === "exporting" || selectedCount === 0
              ? { backgroundColor: "#E8EAED", color: "#9AA0A6" }
              : { backgroundColor: "#111827", color: "#FFFFFF" }
          }
        >
          {status === "exporting" && activeAction === "selected" ? (
            <>
              <Loader2 size={16} strokeWidth={2} className="animate-spin" />
              Exporting...
            </>
          ) : status === "success" && activeAction === "selected" ? (
            <>
              <Check size={16} strokeWidth={2.25} />
              Exported ✓
            </>
          ) : (
            `Export Selected (${selectedCount})`
          )}
        </button>
      </div>

      {status === "exporting" && (
        <div className="rounded-lg border border-[#E5E7EB] bg-[#F9FAFB] p-3 flex flex-col gap-2">
          <p className="text-[12px] text-[#6B7280]">
            {currentIndex === 0
              ? "Preparing exports..."
              : `Exporting ${currentLabel} (${currentIndex}/${queue.length})`}
          </p>
          <div className="h-1.5 w-full rounded-lg bg-[#E5E7EB] overflow-hidden">
            <div
              className="h-full transition-all duration-200 ease-out rounded-lg"
              style={{ width: `${queue.length ? (currentIndex / queue.length) * 100 : 0}%`, backgroundColor: "#111111" }}
            />
          </div>
          <div className="flex flex-col divide-y divide-[#F3F4F6]">
            {queue.map((row) => (
              <ExportQueueRow key={row.key} label={row.label} status={row.status} />
            ))}
          </div>
        </div>
      )}

      {status === "success" && (
        <div className="rounded-lg border border-[#E5E7EB] bg-[#F0FDF4] p-3 flex items-center gap-2 [animation:fp-fade-in_180ms_ease-out]">
          <Check size={16} strokeWidth={2.5} className="text-[#16A34A] shrink-0" />
          <div>
            <p className="text-[12.5px] font-medium text-[#111111]">
              {queue.length} asset{queue.length === 1 ? "" : "s"} exported successfully
            </p>
            <p className="text-[11.5px] text-[#6B7280]">
              {formatLabel} • {qualityLabel}
            </p>
          </div>
        </div>
      )}
    </InspectorCard>
  );
}

const CROP_STRATEGY_OPTIONS = [
  { value: "balanced", label: "Balanced" },
  { value: "subject", label: "Subject First" },
  { value: "landscape", label: "Landscape" },
];

function CropStrategyDropdown({ value, onChange, disabled }) {
  const [open, setOpen] = useState(false);
  const selectedLabel = CROP_PRIORITY_LABELS[value] || "Balanced";

  return (
    <div className="relative">
      <button
        type="button"
        onClick={() => !disabled && setOpen((o) => !o)}
        disabled={disabled}
        className="w-full h-11 flex items-center justify-between rounded-lg border border-[#D1D5DB] bg-white px-3 text-[14px] font-medium leading-5 text-[#111827] transition-colors duration-200 focus:border-[#111111] focus:outline-none disabled:cursor-not-allowed disabled:font-normal disabled:text-[#94A3B8]"
      >
        {selectedLabel}
        <ChevronDown
          size={14}
          className={`text-[#6B7280] transition-transform duration-150 ${open ? "rotate-180" : ""}`}
        />
      </button>

      {open && (
        <>
          <div className="fixed inset-0 z-10" onClick={() => setOpen(false)} />
          <div className="absolute z-20 mt-1.5 w-full rounded-lg border border-[#E5E7EB] bg-white shadow-[0_4px_14px_rgba(17,17,17,0.08)] py-1">
            {CROP_STRATEGY_OPTIONS.map((opt) => {
              const active = opt.value === value;
              return (
                <button
                  key={opt.value}
                  type="button"
                  onClick={() => {
                    onChange(opt.value);
                    setOpen(false);
                  }}
                  className={[
                    "w-full flex items-center justify-between px-3 py-2 text-[13px] text-left transition-colors duration-150",
                    active ? "bg-[#F3F4F6] text-[#111111] font-medium" : "text-[#374151] hover:bg-[#F9FAFB]",
                  ].join(" ")}
                >
                  {opt.label}
                  {active && <Check size={14} className="text-[#111111]" />}
                </button>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

function InspectorPanel({ image, focalPoint, hasImage, setFocalPoint, smartCropEnabled, setSmartCropEnabled, cropPriority, setCropPriority, userDisabledSafeAreaRef, bumpSafeAreaActivity, selected, exportFormat, setExportFormat, quality, setQuality }) {
  const [copied, setCopied] = useState(false);
  const x = Math.round(focalPoint.x);
  const y = Math.round(focalPoint.y);
  const cssString = `object-position: ${x}% ${y}%;`;

  const [pulseX, setPulseX] = useState(false);
  const [pulseY, setPulseY] = useState(false);
  const prevX = useRef(x);
  const prevY = useRef(y);

  useEffect(() => {
    if (prevX.current === x) return;
    prevX.current = x;
    setPulseX(true);
    const t = setTimeout(() => setPulseX(false), 200);
    return () => clearTimeout(t);
  }, [x]);

  useEffect(() => {
    if (prevY.current === y) return;
    prevY.current = y;
    setPulseY(true);
    const t = setTimeout(() => setPulseY(false), 200);
    return () => clearTimeout(t);
  }, [y]);

  const handleCopy = async () => {
    if (!hasImage) return;
    try {
      await navigator.clipboard.writeText(cssString);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // clipboard unavailable — no-op
    }
  };

  const handleReset = () => {
    if (!hasImage) return;
    setFocalPoint({ x: 50, y: 50 });
    // Reset Focus clears the "user disabled Safe Area" preference so the
    // next focal-point interaction can auto-show it again.
    if (userDisabledSafeAreaRef) userDisabledSafeAreaRef.current = false;
  };

  const handleXInputChange = (e) => {
    if (!hasImage) return;
    const raw = e.target.value;
    if (raw === "") return;
    const num = Number(raw);
    if (Number.isNaN(num)) return;
    const clamped = Math.min(100, Math.max(0, num));
    setFocalPoint({ x: clamped, y: focalPoint.y });
    bumpSafeAreaActivity?.();
  };

  const handleYInputChange = (e) => {
    if (!hasImage) return;
    const raw = e.target.value;
    if (raw === "") return;
    const num = Number(raw);
    if (Number.isNaN(num)) return;
    const clamped = Math.min(100, Math.max(0, num));
    setFocalPoint({ x: focalPoint.x, y: clamped });
    bumpSafeAreaActivity?.();
  };

  return (
    <aside className="w-[300px] shrink-0 sticky top-0 self-start h-full overflow-y-auto border-l border-[#E8E8E6] bg-[#FAFAF9] pt-6 px-6 pb-6 flex flex-col gap-4">
      <h2 className="text-[16px] font-semibold text-[#111827] leading-[24px]">Inspector</h2>

      <InspectorCard title="Focus Position">
        <div className="grid grid-cols-2 gap-3">
          <InspectorField
            label="Horizontal"
            value={hasImage ? x : "—"}
            pulse={hasImage && pulseX}
            editable={hasImage}
            disabled={!hasImage}
            onChange={handleXInputChange}
          />
          <InspectorField
            label="Vertical"
            value={hasImage ? y : "—"}
            pulse={hasImage && pulseY}
            editable={hasImage}
            disabled={!hasImage}
            onChange={handleYInputChange}
          />
        </div>

        <button
          type="button"
          onClick={handleReset}
          disabled={!hasImage}
          className={[
            "w-full h-11 flex items-center justify-center rounded-lg text-[14px] font-medium border transition-colors duration-150",
            !hasImage
              ? "font-normal bg-white border-[#E5E7EB] text-[#94A3B8] cursor-not-allowed"
              : x === 50 && y === 50
              ? "bg-[#F3F4F6] border-[#E5E7EB] text-[#111827]"
              : "bg-white border-[#E5E7EB] text-[#111827]",
          ].join(" ")}
        >
          Focus Reset
        </button>
      </InspectorCard>

      <InspectorCard title="Crop Strategy">
        <CropStrategyDropdown
          value={cropPriority}
          onChange={setCropPriority}
          disabled={!hasImage}
        />
      </InspectorCard>

      <InspectorCard title="CSS Output">
        <div className="h-11 rounded-lg border border-[#E5E7EB] bg-[#F3F4F6] px-3 flex items-center overflow-hidden">
          <p
            className={[
              "text-[14px] leading-5 transition-colors duration-200 truncate",
              hasImage ? "font-medium text-[#374151]" : "font-normal text-[#9CA3AF]",
            ].join(" ")}
          >
            {hasImage ? cssString : "object-position: 50% 50%;"}
          </p>
        </div>

        <button
          type="button"
          onClick={handleCopy}
          disabled={!hasImage}
          className={[
            "w-full flex items-center justify-center gap-2 h-11 rounded-lg text-[14px] border",
            "transition-colors duration-150 active:bg-[#ECECEC]",
            hasImage
              ? "font-medium bg-white border-[#E5E7EB] text-[#111111] hover:bg-[#F3F4F6]"
              : "font-normal bg-[#F7F7F8] border-[#E5E7EB] text-[#94A3B8] cursor-not-allowed",
          ].join(" ")}
        >
          {copied ? <Check size={14} strokeWidth={1.75} /> : <Copy size={14} strokeWidth={1.75} />}
          {copied ? "Copied ✓" : "Copy CSS"}
        </button>
      </InspectorCard>

      <ExportAssetsCard
        image={image}
        focalPoint={focalPoint}
        smartCropEnabled={smartCropEnabled}
        cropPriority={cropPriority}
        selected={selected}
        hasImage={hasImage}
        format={exportFormat}
        setFormat={setExportFormat}
        quality={quality}
        setQuality={setQuality}
      />
    </aside>
  );
}

export default function FramePointShell() {
  const [active, setActive] = useState("workspace");
  const [image, setImage] = useState(null); // { src, name, size, width, height }
  const [focalPoint, setFocalPoint] = useState({ x: 50, y: 50 });
  const [smartCropEnabled, setSmartCropEnabled] = useState(true);
  const [cropPriority, setCropPriority] = useState("balanced");
  // Shared export format — auto-detected from the uploaded file's type,
  // and editable via the Export Format pills in the Inspector.
  const [exportFormat, setExportFormat] = useState(null);
  // Shared export quality — the single source of truth for both the actual
  // export logic and the Export Quality dropdown in the Inspector.
  const [quality, setQuality] = useState(2);
  const [safeArea, setSafeArea] = useState(false);
  // Tracks whether the user manually turned Safe Area off. Respected until
  // a new image is uploaded, the image is removed, or Reset Focus is
  // pressed — at which point it's cleared so auto-show can resume.
  const userDisabledSafeAreaRef = useRef(false);
  // 1 = fully visible, 0.25 = dimmed after 2s of no focal-point activity
  // (dragging, clicking, changing viewport chip, or editing coordinates
  // all reset this). It never fully disappears.
  const [safeAreaOpacity, setSafeAreaOpacity] = useState(1);
  const dimTimeoutRef = useRef(null);
  // Preview selection state (checkboxes on each responsive preview card).
  // Lifted to root so both the Responsive Views grid and the Inspector's
  // Export Assets section read/write the exact same selection.
  const [selected, setSelected] = useState(() =>
    Object.fromEntries(PREVIEW_FRAMES.map((f) => [f.key, false]))
  );

  const bumpSafeAreaActivity = () => {
    setSafeAreaOpacity(1);
    if (dimTimeoutRef.current) clearTimeout(dimTimeoutRef.current);
    dimTimeoutRef.current = setTimeout(() => setSafeAreaOpacity(0.25), 2000);
  };

  useEffect(() => {
    return () => {
      if (dimTimeoutRef.current) clearTimeout(dimTimeoutRef.current);
    };
  }, []);

  return (
    <div
      className="w-full h-screen min-h-[640px] flex flex-col"
      style={{ backgroundColor: "#F8F9FB", fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, sans-serif" }}
    >
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&display=swap');
        @keyframes fp-fade-in {
          from { opacity: 0; transform: scale(0.98); }
          to { opacity: 1; transform: scale(1); }
        }
        @keyframes fp-twinkle {
          0%, 100% { opacity: 0; transform: scale(0.6); }
          50% { opacity: 1; transform: scale(1); }
        }
        @keyframes fp-border-pulse {
          0%, 100% { border-color: #9CA3AF; }
          50% { border-color: #6B7280; }
        }
      `}</style>
      <TopBar />
      <div className="flex-1 flex min-h-0">
        <Sidebar active={active} onSelect={setActive} />
        <Workspace
          image={image}
          setImage={setImage}
          focalPoint={focalPoint}
          setFocalPoint={setFocalPoint}
          smartCropEnabled={smartCropEnabled}
          setSmartCropEnabled={setSmartCropEnabled}
          cropPriority={cropPriority}
          setCropPriority={setCropPriority}
          safeArea={safeArea}
          setSafeArea={setSafeArea}
          userDisabledSafeAreaRef={userDisabledSafeAreaRef}
          safeAreaOpacity={safeAreaOpacity}
          bumpSafeAreaActivity={bumpSafeAreaActivity}
          selected={selected}
          setSelected={setSelected}
          exportFormat={exportFormat}
          setExportFormat={setExportFormat}
          quality={quality}
          setQuality={setQuality}
        />
        <InspectorPanel
          image={image}
          focalPoint={focalPoint}
          hasImage={!!image}
          setFocalPoint={setFocalPoint}
          smartCropEnabled={smartCropEnabled}
          setSmartCropEnabled={setSmartCropEnabled}
          cropPriority={cropPriority}
          setCropPriority={setCropPriority}
          userDisabledSafeAreaRef={userDisabledSafeAreaRef}
          bumpSafeAreaActivity={bumpSafeAreaActivity}
          selected={selected}
          exportFormat={exportFormat}
          setExportFormat={setExportFormat}
          quality={quality}
          setQuality={setQuality}
        />
      </div>
    </div>
  );
}
